INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1076270-acct110', 'stk-faisal-fin', 'ACCT 110', 'info', '{"desc": "الكورس الان تغير رمزه وصار 110\nوكمان تغير اسمه وصار financial accounting\n\nالكورس يتكلم عن اساسيات المحاسبة المالية وهي عبارة عن قوائم مالية اربعة اساسية وكيفية كتابتها وتعديلها وتحليلها بشكل مبسط ويتطرق الكورس ايضا لوصف حقوق الشركاء والملاك والمواطنين في المساهمات وايضا انواع الديون على الشركات الخاصة والعامة ورؤوس الاموال والسندات وانواعها كل هذه الامور مهم انك تفهمها عشان تقدر تكتب القوائم والتقارير المالية الاربعة للشركة بشكل صحيح ودقيق\n\nالكورس محتاج تدريب على التمارين بشكل كبير اكثر من القراءة والحفظ وعندك موقع الوايلي بلس لحل الهوموركات والكويزات مفيييد جدا وعليها 15% يعني موثرة في القريد\n\nطلاب المحاسبة مهم جدا انك تفهم الكورس زيييين لانه عصب التخصص وبداية قوية في هذا الكورس بتعطيك دفعة قوية لفهم الكورسات يلي بعدها في المحاسبة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-110-intro-to-financial-accounting/120956/4", "user": "Faisal-FIN", "ts": 1344215651000, "tid": 120956, "pn": 4}}', 1344215651000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1252243-acct110', 'stk-practice', 'ACCT 110', 'info', '{"desc": "بشكل عام الكورس مترابط\n\nالزبدة كلها في اول شابترين والباقية بناء عليهم\n\nيعتبر كورس عادي المياجر والفاينل 95% ريتن و 5% اختيارات\n\nاسئلة كل الدكاترة سهلة الا اللي يحطها المصري الله يعينكم\n\n+ انصح بالابتعاد عن عمر عبد الحليم اذا ما كان تخصصك محاسبة لانك ما تحتاج تسمع للفلسفة والمعاملة السيئة حقته وانصح بالدكتور ميرغني لانه اخلاق ويدف الله يسعده\n\nموفقين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-110-intro-to-financial-accounting/120956/7", "user": "Practice", "ts": 1376199165000, "tid": 120956, "pn": 7}}', 1376199165000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1373857-acct110', 'stk-mhm14', 'ACCT 110', 'info', '{"desc": "Term 132\n\nجودة المقرر بشكل عام: المقرر جدا ممتاز و مستواه مناسب ليس بالسهل و لا بالصعب، وسط\n\nالمواضيع التي يغطيها المقرر: الكورس يتكلم عن أساسيات المحاسبة المالية و كتابة التقارير المالية السنوية و الشهرية، في البداية في أول تشابتر يعطي نبذة عن المحاسبة و أقسامها و أهميتها في الشركات الفردية و شركات المساهمة و غيرها، و بعدها يعلمك على الطريقة الأساسية لكتابة التقارير المالية الأربعة و يعلمك على الدائن و المدين و في أي حالة تكون دائن أو مدين و بعدها يعلمك على تسجيل العمليات المالية اللي تسويها الشركة و كيف تسجل كل عملية في السجلات المالية و بعدها تعمل التقارير المالية السنوية\nو بعدين كل تشابتر من الكتاب يتكلم عن شيء مخصص في التقارير المالية: مثل الأصول و الممتلكات و الديون و الأسهم\n\nالكتاب المستخدم للمقرر: الكتاب جدا جدا ممتاز و و المذاكرة منه يغنيك عن كل المصادر الثانية و طريقة عرض المعلومة ممتازة و لغتها سهلة الفهم\n\nالأسئلة والأمثلة المستخدمة في المقرر: في وسط الدروس تكون في أمثلة معطاة و بعدها يعطيك سؤال على نفس الفكرة و حلها موجود و في نهاية كل تشابتر يكون هناك مجموعة أسئلة ممتازة و مفيدة و مذاكرة هذه الأسئلة تضمن لك الدرجات العالية في الكورس إن شاء الله\n\nمدى فائدته في الناحية التطبيقية: الكورس هذا يبني الأساس في تخصص المحاسبة و هو مهم جدا لمن داخل في التخصص و كذلك مهم لكورسات قادمة في المحاسبة و المالية، فهمك لهذا الكورس بريحيك من التعب بعدين و لابد تكون متقن للمواضيع التي تغطيها الكورس و خصوصا إذا كنت طالب محاسبة\nالمذاكرة من الكتاب هو الأساس، كثير من الطلاب يذاكروا من السلايدات بعدين يجيبوا درجات سيئة\nو حل المسائل و التعود عليها مهم حتى للوظيفة مستقبلا\nكورس ممتع ليس بالسهل و لا بالصعب لكن يحتاج متابعة أول بأول و حل مسائل كثير و الدروس نوعا ما طويلة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-110-intro-to-financial-accounting/120956/8", "user": "MHM14", "ts": 1401360809000, "tid": 120956, "pn": 8}}', 1401360809000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1471658-acct110', 'stk-user8581', 'ACCT 110', 'info', '{"desc": "الكورس كان اسمه 201\nوهذا تقييم الطلاب , وأتمنى الإدارة تقفل هذا الموضوع وتعدل على عنوان الموضوع القديم عشات لايتشتتوا الشباب\nACCT 201 Principles of Accounting\nويعطيكم العافية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-110-intro-to-financial-accounting/120956/12", "user": "user8581", "ts": 1492641399000, "tid": 120956, "pn": 12}}', 1492641399000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1474264-acct110', 'stk-maxmx05', 'ACCT 110', 'info', '{"desc": "جودة المقرر بشكل عام : ممتاز واساسي لطالب تخصص المحاسبة هذا هو اساس المحاسبة اللي راح ينبني عليه بقية الكورسات\n\nالمواضيع التي يغطيها المقرر : يبدا باساس المحاسبة من المعادلة الرائيسية للمحاسبة الى الضريبة و الربح و الخسارة و و و\n\nالكتاب المستخدم للمقرر : من افضل الكتب اللي راح تشوفها في حساتك , اعتقد الكتاب الى حد ما يكفيك عن المدرس\n\nالأسئلة والأمثلة المستخدمة في المقرر : ممتازة جدا وتغطي المفاهيم الرئيسية للشابتر بشكل عام\n\nمدى فائدته في الناحية التطبيقية : جدا مهم هذا الكورس\n\nللخروج من هذا الكورس بقريد عالي ( B+ ) وفوق انصح بالاتي :\n\n1- ذاكر من الكتاب , الكتاب طويل جدا وكل ما تروح بعيد يطول اكثر لكنه في المقابل في حشو معلومات بشكل رهيب جدا , فذاكر اول باول ولخص كل تشابر في ورق عشان بعدين اذا جيت تذاكر ترتاح\n\n2- الهوم ورك : بغض النظر كونه يمثل ( 15% ) من الكورس ( تقريبا 3 قريدات ) , الهومورك في هذه المادة مهم بشكل كبير كون اسئلة المياجر تجي منه وتغطي افكاره\n\n3- الهاند اوت : بعد ما تذاكر الكتاب وبعدين تروح على الهوم ورك وتحلة روح على الهاندوت وفهمه لا تحفظ وحل بناء على فهمك\n\nاضمن لك اذا ذاكرت من هذه المصادر الثلاث انك راح تجيب فوق 70% من الاختبار\n\n- هذا الكورس يحتاج الى متابعة من البدابة ولا راح يتعبك معاه\n\nنطاق الـ C كبير جدا يمكن يبدا من 60 او يمكن اقل لان يمكن كان مجموعي حدود 54-60 , وطلعت بـ C", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-110-intro-to-financial-accounting/120956/13", "user": "Maxmx05", "ts": 1496265642000, "tid": 120956, "pn": 13}}', 1496265642000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1507352-acct110', 'stk-kbsc', 'ACCT 110', 'info', '{"desc": "- جودة المقرر بشكل عام\n\nممتاز\n\n- المواضيع التي يغطيها المقرر\n\nBasic accounting principles\n\n- الكتاب المستخدم للمقرر\n\nFinancial accounting\n\n- طريقة مذاكرة المقرر\n\nBook + manual sloution or Book + wiely home work\n\n- إضافات\n\nالكورس سهل و ممتع جدّاً و لكن يحتاج تدريب و تحريك يد ، و اللي بيزيد فهمك التدريب ، ٧٥٪؜ من الطلاب يفهمون الكورس هذا أو أي كورس أكاونتنق بالتدريب و الآخرين أُنعموا بقدرة الفهم و التدريب عندهم ليس بالضرورة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-110-intro-to-financial-accounting/120956/15", "user": "KBSC", "ts": 1552815891000, "tid": 120956, "pn": 15}}', 1552815891000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p613404-acct110', 'stk-user3328', 'ACCT 110', 'info', '{"desc": "الشرح ماتوقع فيه أحد في الجامعه كلها مثل شرح عمر\n\n<< آسف على المبآلغه ،، بس إذآ درست عنده رآح تعرف 🙂\n\nنزل عند عمر وأنت مغمض ،، ولاتغيب ولا كلآس علشآن تفهم الماتيريال صح\nالكوزات سهله جدا وعليها 20 %،، ذآكر الهاند آوتس وتاخذ عشر كوزات كل واحد عليه درجتين\n\nوالكلاس وورك عليها 10% … يشرح لك مثآل ويعطيك سؤال نفس المثآل علشان تاخذ عليه درجه ،، لك عشر أسئله كلاس وورك على مدار الترم كل واحد عليه درجه وحده\n\nالدرجات يقول كل واحد له حقه بس أتسآعد مع الطلاب اللي على البوردر وأزودهم\n\nطبعا الكوزات والكلاس وورك هذي 30 % والميدتيرم 35% والفاينل 35% …\n\nمثل ماقلت لك لاتفوت عمر أبدا ،، خصوصا لو كان تخصصك أكاونتنق 😉\n\nمحمد ميرغني هذآ جديد مادري عنه … أعرف ميرغني أحمد بس 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct201/88635/2", "user": "user3328", "ts": 1274604994000, "tid": 88635, "pn": 2}}', 1274604994000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p136004-acct110', 'stk-high_voltage', 'ACCT 110', 'info', '{"desc": "* تعاونوا على البر و التقوى… و لا تعاونوا على الإثم و العدوان…\n\n* الساكت عن الحق شيطان اخرس…\n\nعزيزي “بي عن وجهك”\nاولا… عندما يعطيك الدكتور Homework فهو يتوقع منك ان تحله بنفسك…\nو ثانيا: اذا حليته بنفسك حتفهم الدرس و هذا المطلوب من حضورك للمحاضرة…\nثالثا: اذا فهمت الدرس… حتستفيد انت في المستقبل و حتفيد بلدك…\nرابعا: اذا غشيت و نقلت الحل من شخص اخر فلن تفهم الدرس و في الاختبار النهائي ستعتمد نفس الاسلوب وهو “الغش”… و لا اريد ان اذكرك ان رسولنا و حبيبنا محمد صلى الله عليه و سلم نهى عن الغش…\nخامسا و اخيرا: اعتبرها محاولة مني لتنزيل المعدل @18@\n\nملاحضة: انا خلصت المادة من سنتين و لا اعرف احد منزل المادة عشان ماتقولي بأنزل المعدل عشان شخص و لا على حساب شخص @37@", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-201-hw-solution-ch4-ch5/53518/6", "user": "High_Voltage", "ts": 1164803635000, "tid": 53518, "pn": 6}}', 1164803635000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p347965-acct110', 'stk-user1839', 'ACCT 110', 'info', '{"desc": "دكتور عمر\n\nجيد جدا\nو مفيد\nو يشرح بإخلاص و تفاني\n\nمشكلته انه يشرح دائما لكنه ظريف و كوميدي ( أخو عادل إمام في الكوميديا)\n\nو من مشاكله كثرة الهوموركات ( الحلول في المانوال)\nو كثرة كويزاته\nو مياجره على قد شرحه\n\nأنصح به أبناء التخصص المحاسبي\nأما بقية الدكاترة فلا علم لدي عنهم…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-201/68951/2", "user": "user1839", "ts": 1231103038000, "tid": 68951, "pn": 2}}', 1231103038000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1263850-acct110', 'stk-ambitious_91', 'ACCT 110', 'info', '{"desc": "أهلن مين مدرسك اذا تسمح لي أسأل؟؟؟ عبد الحليم؟ اذا أيه اية وقت ١١ أو ١ ؟؟\nعالعموم, أنا منزل نفس الكورس, مالك الا الكتاب تقراه وتفهم منه, وتحل الأسئلة نهاية التشابتر, هناك النظرية على المفاهيم وسهله وحلولها فيه, وأسئلة الحسابات مالها حلول شوف الأمثلة محلوله وحاول تحل اذا فيه الحلول, هذا اللي أسويه…\nوعندك مثلا في موقع الكتاب WillyPlus سلايدات كويسه وملخصت الكتاب والمهم, بس فضلت أنا اني أقرأ الكتاب وارتبط به أفضل لي من المذاكره عالشاشه!!! شي آخر في كويزات في الموقع, كويس لو تحلها بعد الانتهاء من مذاكرة التشابتر…\n\nهذا اللي عندي وطريقتي و أحس أنها كويسه وأملي فيها, وبحثت عن سلوشن مانيوال للكتاب عالنت بس ما حصلت, ياليت اللي يحصل يرفع الملف\nوشككككررراا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-110/149142/5", "user": "ambitious_91", "ts": 1379178510000, "tid": 149142, "pn": 5}}', 1379178510000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1091084-acct110', 'stk-pes13', 'ACCT 110', 'info', '{"desc": "نصيحة خذها مني للتاريخ 🤠. الكورس هذا أهم كورس للطالب اللي تخصصه محاسبة أو مالية. أفهم وأفهم الكتاب, ولا تعتمد على السلايدات, الا في حالة أنك فقط ترتب أفكارك.\nطبعا للمعلومية,تخصصي محاسبة و الترم هذا اخر ترم لي في الجامعة وراح أتخرج أن شاء الله وراح أخليك أنت وجامعتك اللي مافيها مواقف ههههههههههههه,دعابة دعابة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-acct-110/129702/6", "user": "pes13", "ts": 1347400574000, "tid": 129702, "pn": 6}}', 1347400574000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1442367-acct110', 'stk-user10207', 'ACCT 110', 'info', '{"desc": "الصح والخطأ: تكون حسب فهمك من قراءة الشبتر. نصها حسابات ونصها تعاريف. متوسطة الصعوبة والاختيارات تلخبط بس يمديك تحلها كلها.\n\nالمقالي: مااتذكرها كلها بالضبط بس انها سهلة. واحد من الاسئلة يقول: وش سبب الاخطاء الي تصير كتابة القوائم المالية.\nالاسئلة طبعا من عندهم. ماينفع تذاكر تست بانك ولاغيره.\n\nالمسائل: الميجر الاول بتسوي القوائم المالية التالية + adjustment:\nincome statement\nstatement of financial position\nretained earning statement\n\nومسألة ثانية تسوي Adjustment\n\nالمسائلة سهلة والارقام بسيطة عشان تسهل لك الحل.*\nالمسائل هي اهم شيء الي عليها points. اكثر من المقالية والاختيارات.\n\nبالتوفيق.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/first-major-acct-110/172291/3", "user": "user10207", "ts": 1455714292000, "tid": 172291, "pn": 3}}', 1455714292000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p152293-acct110', 'stk-masm007sa', 'ACCT 110', 'srcU', '{"html": "بس قي ال course description مكتوب prequiste: sphomore standing ؟؟؟ عندك فكرة عن هذا الكلام<br><br>في مخالفات التسجيل الذي نشرها مكتب مسجل الجامعة مؤخرًا ذكرة هذه المخالفة كالتالي<br><br>المخالفة الثانية عشرة:<br>تسجيل الطالب في مقرر له متطلبات خاصة. ( مستوى / تخصص / كلية … الخ).<br>الإجراء في مكتب مسجل الجامعة:<br>سوف يستمر الطالب في المقرر بموافقة رئيس القسم مع عميد الكلية، يمكن حذف المقرر من الطالب<br><br>وقد تم ارسال ملفين باللغة العربية والإنجليزية(لجميع طلاب الجامعة على البريد الإلكتروني) بخصوص مخالفات التسجيل وكيفية التعامل معها وهي متوفرة في مبنى 9<br><br>ملاحظة: يوجد ملف مرفق بهذا الرد يجنزي على مخالفات التسجيل<br><br>تحياتي<br><br>أخوك<br><br>أبو جاسم<br><br>​<span data-fid=\"stk-f152293-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f152293-0": {"name": "registeration violations.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-201-requirments/54916/6", "user": "masm007sa", "ts": 1171349572000, "tid": 54916, "pn": 6}}', 1171349572000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p76298-acct110', 'stk-user1052', 'ACCT 110', 'srcP', '{"html": "ACCT202<br><br>​<span data-fid=\"stk-f76298-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f76298-0": {"name": "acct202.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/a47745fa1d3d58b7fd73c155c85f45e021b868961273de4323674a158aae04c3"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-201-homeworks-solution/47989/4", "user": "user1052", "ts": 1116948749000, "tid": 47989, "pn": 4}}', 1116948749000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p76482-acct110', 'stk-alumni', 'ACCT 110', 'srcP', '{"html": "الأخ أدفايزر …<br><br>السلام عليكم ورحمة الله<br><br>نعم … أنا معك بأن لها أيجابياتها وسلبياتها … ولكن هذا اذا كان المدرس 100% فاهم المنهج ويعرف كيف يوصل المعلومة ومهتم بالطالب …<br><br>في كثير من المسائل في المحاسبة والفيزياء والكيمياء تستعصي على الطالب … واذا تمرن عليها قبل الامتحان تكون جدا سهلة يوم الامتحان ويدعي للي أعطاه الحلول … وكذا يضمن القرييييييييييييييييييد ( +A )<br><br>الأخ عصام<br><br>مرفق الواجبات لمادة المحاسبة 201<br>جميع حلول المسائل موجودة عندي … مش بس الواجبات…<br><br>اذا احتجتها … عطني خبر…<br><br>أتمنى لكم التوفيق<br><br>أخوكم<br><br>​<span data-fid=\"stk-f76482-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f76482-0": {"name": "homework.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/213a34213e52cc16513f047c9594eddc070526c316157d05af3198cd7e40d055"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-201-homeworks-solution/47989/8", "user": "Alumni", "ts": 1117282763000, "tid": 47989, "pn": 8}}', 1117282763000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p198908-acct110', 'stk-pe24te', 'ACCT 110', 'srcU', '{"html": "Acct201<br><br>​<span data-fid=\"stk-f198908-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f198908-0": {"name": "ACCT 201 Course Syllabus (061).doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/79ce9cc4d31e1701d8a874e26b3214e87e69b42586a7df20328d84362d8d053b"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syllabus/58311/7", "user": "pe24te", "ts": 1188876398000, "tid": 58311, "pn": 7}}', 1188876398000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-anoosh-acct110', 'stk-anoosh', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98419", "n": "Dr. Muhammad Shahidulislam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الكورس Acct 201\n\nالتحضير :\nيوميا آخر الكلاس وبعض الاحيان ببدايته بس ما يحاسب على التأخير ابدا\n\nطريقة الشرح :\nعلى السلايدات ممتاز شرحه وفي موقع الكتاب (وايلي بلس) يشجعك تستخدمه مفيد جداً\nويحل تمارين على السبورة والاكسل\n\nالكويزات :\nصعبة بس تخليك تذاكر للميدترم والفاينل 7 كويزات ياخذ افضل 5\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nسمعنا عنه انه يدف بس للأسف آخر الترم كل المدرسين\nارسلو مجموع السكورز للكوردنيتر (مدني) وهو اللي حط القريدات 😞\nاتوقع لو كان الموضوع بيد استاذ شهيد ما كان راح يقصر\n\nالصوت:\nواضح\n\nإضافات :\nاستاذ اخلاق ومتفاهم ودايم يقول لنا “you’re like my sons”\nمشغول جدا جدا عنده اشياء كثيرة غير التدريس\nبعض الاحيان يجي متأخر بس ما يغيب 🤠\nايضا عنده خبرة كبيرة في السوق السعودية راح تسفيد من خبرته\n\nسواء كنت اكاوتنغ او لا انصحك تنزل عنده ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p841327-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-shahidulislam/98419/7", "user": "Anoosh", "ts": 1304708620000, "tid": 98419, "pn": 7}}]}', 1304708620000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sultan_salman_1419-acct110', 'stk-sultan_salman_1419', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98419", "n": "Dr. Muhammad Shahidulislam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Acct 110 … Term 171\n\nالتحضير : مافيه وقت محدد … مرات يحضر في البداية ومرات يحضر في النهاية … لكن إذا حضر في البداية يحضر أكثر من مرة\n\nطريقة الشرح : جيد جدا إلى ممتاز … في بعض الأحيان يكون ممل بسبب السلايدات … لكن بشكل عام ممكن تطلع بفائدة كبيرة من الكلاس\n\nالكويزات : اختيار من متعدد من التيست بانك … متوسطة الصعوبة\n\nالمياجر: 75%-85% مقالي و 15%-25% اختيار من متعدد … متساهل في موضوع التصحيح … لكن لا تترك أي شي فاضي\n\nالفاينل : نفس النسبة اللي ذكرتها فوق للمياجر … أعتبره أسهل من المياجر … ولكن يحتاج لمذاكرة جادة\n\nالقريد النهائي: +B\n\nالصوت: متوسط ولكن يفضل الجلوس في الأمام\n\nإضافات : مدرس طيب وخلوق ومتعاون … حاول تحضر حصص الهيلب سشن اللي يسويها قبل المياجر والفاينل مهمة جدا جدا عنده وتجي أسئلة منها في المياجر والفاينل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1486333-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-shahidulislam/98419/10", "user": "sultan_salman_1419", "ts": 1516278277000, "tid": 98419, "pn": 10}}]}', 1516278277000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-makkahboy-acct110', 'stk-makkahboy', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98419", "n": "Dr. Muhammad Shahidulislam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله\nACCT110 - 171\nالتحضير : يحضر في بداية الكلاس بالأسماء من البلاكبورد، واللي جاء متأخر يحضره بنهاية الكلاس\nالشرح: يستخدم السلايدات للشرح وبنهاية كل شابتر أو قبل المياجر يحل سؤال كومريهنسف عن الشابتر (يعني يلخص لك الشابتر من الألف للياء) وتقدر تسأله وقتها عن أيييي شي ويششششرح لك بشكل طيب ماشاء الله\n\nالكويزات: الكويزات أونلاين طبعا وسهلة تغطي لك الشابتر بالكامل (تمثل استعداد جيد للمياجر)\n\nالمياجر: سهلة وشخصيا أشوف قسم المحاسبة من الأقسام اللي تتساهل مع الطلاب كثير اذكر في وحدة من المياجر كان واحد من الدكاترة يقول أنه ماله داعي أحد يغش لأننا سهلنا الاختبار لأبعد درجة وفعلا المياجر سهلة بس لو غطيت المنهج! (يعني مو يجي واحد ما ذاكر المنهج ويقول والله صعب)\n\nالفاينل: سهل ومش كومبريهنسف ف سهالات صراحة…\n\nالصوت: صوته رهيييييب صراحة وماتوقعته كذا أبدا ، عنده اكسنت أمريكي رهيييييب ماشاء الله عليه وسلس جدا وصوته واضح ومسموع\n\nإضافات: المادة معه سهلة تبارك الرحمن ، بنهاية السمستر يدف أغلب الشباب (اقول أغلب لانه بعض الشباب يقولو مادفهم) لكن عموما الدكتور متفهم وحبيب جدا ومتساهل مع الطلاب ومايقصر. طريقة المذاكرة للمادة يكفي التركيز مع الدكتور في شرح السلايدات و حل أسئلة الكتاب (حلول الأسئلة موجودة وتتلاقى عند الطلاب) ووضعك في السلليييييم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493669-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-shahidulislam/98419/12", "user": "makkahboy", "ts": 1528080074000, "tid": 98419, "pn": 12}}]}', 1528080074000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_182-acct110', 'stk-_182', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98419", "n": "Dr. Muhammad Shahidulislam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT110-172\n\nالتحضير: بداية أو نهاية المحاضرة، ولا أذكر أنه سجل أحد تأخير\nطريقة الشرح: باوربوينت ويكتب على السبورة إذا لزم\nالكويزات: ما أذكر عددها ولكن سهلة جدًّا، أحيان وهو يشرح يقول:“ترى هذا سؤال بيجي في الكويز”\nالمياجر: موحدة\nالفاينلات: موحدة\nالقريد النهائي: +A\nالصوت: واضح، ولا أظن أني سمعت أستاذًا يتحدث أفضل منه\nإضافات:\n\n- الدكتور حبيب جدًّا، ومثل ما ذكرت فوق ما أذكر سجل أحد تأخير، مع أنه يا كثر اللي يتأخرون، إذا غبت فما تحتاج عذر رسمي، بالذات إذا كان يعرف مستواك\n- الشرح واضح ولغته ممتازة، ما يمانع من إعادة النقاط أكثر من مرة، حريص على تفهيم الطالب\n- منضبط بساعاته المكتبية، ويرد على الإيميل\n- الدكتور متمكن من المادة، ويكفيك أنه خرّيج هارفرد\n\nبشكل عام جميع أساتذة ACCT110,210 ممتازين، لكن إذا حصل لك شهيد فلا تضيّعه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1506106-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-shahidulislam/98419/17", "user": "_182", "ts": 1550255238000, "tid": 98419, "pn": 17}}]}', 1550255238000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-acct110', 'stk-sadguts', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98419", "n": "Dr. Muhammad Shahidulislam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT110-192\nالتحضير : يحضر بعد ٥ دقايق ومايفرق معه التاخير بس مايحب احد يتاخر\nالشرح : ممتاز جدا جدا تفهم كل شيء معاه متمكن من الماده لابعد درجه\nالكويزات : سهله ويختبر كويزات كثير ويحذف اقل واحد\nاضافات : الدكتور شهيد وعمرو كلهم ممتازين في الشرح وانصح بالمذاكره من الكتاب والتدريب على وايلي بلس الموقع ممتاز جدا حل الاسايمنت وتدرب عالاوريون غالبا اسئله المياجر تكون بنفس المستوى “صعبه”", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521782-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-shahidulislam/98419/19", "user": "SadGuts", "ts": 1588674189000, "tid": 98419, "pn": 19}}]}', 1588674189000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mlekon-acct110', 'stk-mlekon', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98419", "n": "Dr. Muhammad Shahidulislam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT110-191\nالتحضير : يحضر بعد بداية لكلاس بشوي وما يدقق على التأخير بس لا تفلها لأنه ممكن يفصل عليك\nالشرح : ممتاز جدا شرح بسيط ويوصل المعلومة بدون فلسفة\nالكويزات : سهله ويختبر كويزات كثير ويحذف اقل واحد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529312-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-shahidulislam/98419/21", "user": "MLEKON", "ts": 1617432282000, "tid": 98419, "pn": 21}}]}', 1617432282000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8025-acct110', 'stk-user8025', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98423", "n": "Dr. Abdullah D. Alharbi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كيف الحال شباب انا اخذت عنده Acct 201\nالتحضير : دائما يحضر بداية الكلاس وغير متفهم ابدا\nطريقة الشرح : جدا سيء متخرج من جامعة سعود\nالكويزات : مافي كويزات\nالمياجر: ملتبلشويز فيها نوعا من الاصعوبه\nالفاينلات : نف المياجر\nالقريد النهائي: f\nالصوت: واضح بس اللهجه شبه سيئه\nإضافات :الدكتور هذا جدا مغرور وغير محترم بتاتا ويعامل الطلاب كأنهم حشرات ووقت ماأخذت معه في طالب اخذ عنده 59 و الدي كانت 60 ومع ذلك عطاه f لا احد يفكر اني حاقد عليه ترى انا ماخذ عنوا بي بس من اجتهادي لكن هالانسان جدا متعااااال ومتكبر ويقهر ودك انك لمن تخلص الكورس تروح وتهزا فيه ماانصح احد ياخذ عندوا …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p789944-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdullah-d-alharbi/98423/2", "user": "user8025", "ts": 1297694938000, "tid": 98423, "pn": 2}}]}', 1297694938000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sendebad-acct110', 'stk-sendebad', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98437", "n": "Dr. Mohammad Talha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نزلت عنده Acct201\nبصراحة … كرهت المادة بسبته !\nشرح … صفر\nتعامل … صفر\nويوم جا اخر السمستر … جا يتمصلح عشان نعطيه ايفاليوويشن حلو !\n\nالقريد النهائي : D", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p772041-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-talha/98437/7", "user": "SENDEBAD", "ts": 1295880987000, "tid": 98437, "pn": 7}}]}', 1295880987000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hisham.s-acct110', 'stk-hisham.s', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98437", "n": "Dr. Mohammad Talha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا معاه حالياً acct 110\n\nالتحضير مثل فرض الصلاة\nبعض المرات يتأخرون الطلاب ٥ - ١٠ دقايق يطردهم او يعطيهم غياب\n\nكلامه كثير ويصيع الوقت بالكلام والهواش ثم يقول وقتي قصير وما عندي وقت\n\nالحق انه يبي مصلحة الطلاب ويحط هلب سشنات لكل تشابتر بنهاية التشابتر\n\nغير متعاون نوعا ما …\n\nفاهم الماده لكن مهنا زود شرح\nلهجته فهمها نوعا ما صعبه للي ماتعود على الهنود ولكن شيء طبيعي تتعود عليه\n\nعموما طلاب التخصص لاتنزلون معاه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1123273-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-talha/98437/16", "user": "hisham.s", "ts": 1353793872000, "tid": 98437, "pn": 16}}]}', 1353793872000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2838-acct110', 'stk-user2838', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98438", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :\nيحضر آخر الكلاس ، ما عنده مشكلة مع التأخير أبد …\nطريقة الشرح :\nسلايدات و يشرح وهو جالس … لكنه يحل مسائل على السبورة و يوصل المعلومة بشكل حلو\nالكويزات :\nمتوسطة الصعوبة\nالمياجر:\nطويلة بشكل عام بس سهلة نسبياً\nالفاينلات :\nنفس فكرة المياجر … فيه ميزة خرافية … التصحيح عنده ملكي … تحل نص السؤال تاخذ درجة تحط قاعدة تاخذ درجة تكتب اسمك تاخذ درجة 🙂\nالقريد النهائي:\nB+\nالصوت:\nواضح نوعاً ما ، ما فيه مشاكل\nإضافات :\nأنا نزلت عنده Acct201 بعد ما حذفتها مع طلحة … بصراحة المدرس حبوب و يوصل المعلومة …\nو حتى في القريدات اذا ما ساعدك ما يظلمك ابد … طبعا هو يعطي بونص للي ما يغيبون\nأهم شي لا تحسسه انك لعاب عنده و ركز معاه في اللاب و ابشر بقريد طيب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p891237-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/6", "user": "user2838", "ts": 1314164436000, "tid": 98438, "pn": 6}}]}', 1314164436000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s.a.l.m.a.n-acct110', 'stk-s.a.l.m.a.n', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98438", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده acct201 قبل سنه تقريبا\n\nالتحضير :\nيحضر يوميا بآخر المحاضره ويسلك التأخير احيانا\n\nطريقة الشرح :\nسلايدات + يحل مسائل على السبوره\n\nالكويزات :\nمتوسطه\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nB\n\nالصوت:\nواضح\n\nإضافات :\nالدكتور حبيب وطيب , لكن كلاسه كان ممل بالنسبه لي , التصحيح حلو , احيانا يعامل الطلاب كأنهم أطفال\nلكن عموما طيب\nلو عاد بي الزمن هل بنزل عنده ؟ لا , الا اذا كان هو افضل الموجود", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1057392-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/9", "user": "S.a.l.m.a.n", "ts": 1340115877000, "tid": 98438, "pn": 9}}]}', 1340115877000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_assan-acct110', 'stk-_assan', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98438", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT110 Term 141\n\nالتحضير : آخر الكلاس\n\nطريقة الشرح : سلايدات والشرح ممل نوعا ما بالرغم إنه يتعب في الشرح ويحاول يوصل المعلومة باللي يقدر عليه (7 من 10)\n\nالكويزات : ماكان يعطينا كوزات\n\nالهوموركات : فيه هومورك اونلاين + عطانا كم هومورك خفيف ويشيك على السريع اللي حل واللي ماحل (يحله معانا بعدين على البورد)\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B+\n\nالصوت: واضح لكن الأكسنت لك عليه\n\nإضافات : المدرس طيب وحبوب , يعصب إذا تكرر التأخير أو ماجبت الكتاب , يعطي بونس , تأخر علينا في المنهج وعطانا كلاسات إضافية (اللي يحضر يعطيه بونس)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1424529-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/14", "user": "_assan", "ts": 1439978942000, "tid": 98438, "pn": 14}}]}', 1439978942000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mfalkhalifah-acct110', 'stk-mfalkhalifah', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98438", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT110 - T 151\nالتحضير : آخر الكلاس\n\nطريقة الشرح : سلايدات و من الكتاب و مرات يجيب معاه أوراق عمل و يوزعها على الطلاب المدرس يحاول بكل ما أوتي من جهد أنه يطلعك من الكلاس فاهم\n\nالكويزات : مافيه كوزات\n\nالهوموركات : فيه هومورك اونلاين + يعطي هوموركات مثلا يقول هذا السؤال حلوه لكن ما يشيك لأنه يقول it is for you own benifit\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B+\n\nالصوت: واضح لكن الأكسنت لك عليه\n\nإضافات : المدرس طيب وحبوب , يعصب إذا تكرر التأخير أو ماجبت الكتاب , يعطي بونس , تأخر علينا في المنهج وعطانا كلاسات إضافية (اللي يحضر يعطيه بونس)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1451028-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/16", "user": "mfalkhalifah", "ts": 1464937430000, "tid": 98438, "pn": 16}}]}', 1464937430000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9921-acct110', 'stk-user9921', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98438", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 161 Acct 110\nالتحضير :\nآخر الكلاس وما يشدّد ع التأخير\n\nطريقة الشرح :\nيفتح البوربوينت ويشرح عليه والمسائل يحللها ع السبورة ، وبعد ما يخلص الشابتر يحل أسئلة فيها كل أفكار الشابتر\n\nالكويزات :\n\nالمياجر:\nمتوسطة الصعوبة ، قبل المياجر والفاينلات عطانا كلاسات إضافية فيها أهم المسائل العملية والأشياء اللي تحتاج حفظ\n\nالفاينلات : متوسط الصعوبة\n\nالقريد النهائي: A\n\nالصوت: واضح ومفهوم\n\nإضافات :\nالدكتور شرّيح ومتساعد في التصحيح وأهم ميزة فيه عن غيره كلاساته الإضافية اللي تفيد كثير في المياجر والفاينلات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466393-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/17", "user": "user9921", "ts": 1484610931000, "tid": 98438, "pn": 17}}]}', 1484610931000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ky_95-acct110', 'stk-ky_95', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98438", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :\nشوف هو يحضر نهاية الكلاس ويمكن لو تروح وتكلمه عن غياب او غيابين بالكثير ممكن يمشيهم لك + ممكن تكلمه قبل الكلاس تطلب منه انك تطلع عشان ظرف او شي وهو يتفهم بس انتبه يسجل عليك غياب حاول قد ما تقدر انه ما يتسجل عليك ولا غياب عنده لانه ما راح يتذكرك الدكتور الا بعدد غياباتك.\n\nطريقة الشرح :\nبالبداية ع السبورة بس مع تقدم المنهج صار يفتح السلايدات ويشرح منها واذا فيه مسائل بيحلها لك ع السبورة.\n\nالكويزات :\nانا اخذت عنده ACCT 110 في ترم 162 وما عطانا اي كويز.\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nB+\n\nالصوت:\nواضح\n\nإضافات :\nشوف الدكتور والله ما يقصر مع الطلاب بس اللي يبغاه انه الطالب يكون شاد حيله معاه وزي ما قلت فوق الدكتور ما يعرفك الا بعدد غياباتك + قبل الاختبارات يسوي مراجعه احرص انك تحضرها لانه تقريبا هذي المراجعه يركزلك فيها ع الاشياء المهمة اللي بتجي بالاختبار وانت كل اللي عليك انت تحدد الاسئلة اللي بيذكرها الدكتور بالشرح.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1482568-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/19", "user": "ky_95", "ts": 1509209235000, "tid": 98438, "pn": 19}}]}', 1509209235000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullahsk-acct110', 'stk-abdullahsk', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98438", "n": "Dr. Mirghani Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT110 -171\nالدكتور حبيب وخلوق جدا\nيحضر دائما بالأسماء\nشرحه ممتاز ويعطي امثلة >> غالبا يكتب عالسبورة\nما يعطي كويزات ويكتفي بالاونلاين كويز والهوموورك\nبالنسبة للتصحيح الدكتور يعطيك حقك\n\nسلبياته:\nتأخير التصحيح + الفاينل ما اعطانا الدرجات واكتفى بوضع القريد في البورتال.\n\nأخيرا،،،انصح بالدكتور والدكتور متعاون بشكل لا يوصف لدرجة كنت اشوفه يشرح لبعض الطلاب بعد الكلاس عند الجلسات اللي في ٢٤.\n\n+ الأفضل انك تحل الهوموورك بنفسك لأن أسئلة المياجر بتجي مشابهة لها .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1486370-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mirghani-ahmed/98438/21", "user": "abdullahsk", "ts": 1516345077000, "tid": 98438, "pn": 21}}]}', 1516345077000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3328-acct110', 'stk-user3328', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كورس acct201 - ترم 082\n\nالتحضير\nكل محاضره من خلال ورقه يوقع عليها الطلاب ويتضايق كثير من المتأخرين وممكن يروح نص ساعه في الكلام عليهم والشرشحه في باقي الطلاب\n\nطريقة الشرح\nالأفضل في مجاله بلا منازع … ملك الشرح في وجه نظري،، لو تكون منتبه معه ماراح تفوت شيء أبدا وماراح تطلع من الكلاس الا فاهم وبقوه\n\nالكويزات\nتافهه جدا ومن شرحه … افهم معه وتجيب فيها فل مارك … كل الكوزات ماعدا أول واحد(كان أسئله اختيارات على الأساسيات في الكورس) كانت كلها مسائل من الهاند اوت اللي يعطيها الطلاب\n\nالمياجر\nكان ميدتيرم وكان متوسط … المحاسبه بشكل عام تعتمد على حل المسائل وقد ماتحل على الأفكار قبل الاختبار راح تحل مثلها في الاختبار\n\nالفاينلات\nنفس الكلام على الميدتيرم\n\nالقريد النهائي\n+A\nالدكتور مافيه كلام لكنه شديد على الطلاب ويذلهم ويشرشحهم (يعني لو ماتقدر تمسك نفسك لاتنزل عنده) مع انه يعجبني نوعيته من الدكاتره\nغير أنه الدكتور اذا كان مروق يكون مرح ونكتي وتستمع بالكلاس معه …\n\nالصوت\nواضح جدا … حتى انه الدكتور اللي بالكلاس الثاني كان دائما يجي يشتكي من الازعاج\n\nإضافات\nبالنسبه لطلاب المحاسبه … فـ لو مانزلوا معه الـ201 فهم راح يفقدوا متعة المحاسبه لأنه دراسة هالكورس عند عمرو من أهم الأمور بالنسبه لطالب المحاسبه(في رأيي المتواضع) … راح يفهمك بشكل ماراح تنساه لوقت طويل جدا … غير أن أكثر كورسات المحاسبه اذا ماهو كلها تعتمد على الأساسيات اللي تُدرس في الـ201 …\nالدكتور يحب الطلاب يكونوا منتبهين على الدوام … وفيه 10 درجات على الكلاس وورك وهي على طول السمستر يحل مسأله ثم يسأل سؤال مشابه وتحله على ورقه على ال10 شباتر أو 11 اللي تاخذها وكل واحد عليه درجه … الدكتور راح يزودك في الكلاس وورك والكوزات بس في القريد النهائي ماظنيت أبدا أبدا …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p789997-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/6", "user": "user3328", "ts": 1297698535000, "tid": 98439, "pn": 6}}]}', 1297698535000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3257-acct110', 'stk-user3257', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "تقييمي له من خلال كورس ACCT201\n\nالتحضير :\nكل محاضرة وكل لاب يوزع ورقة التوقيع على الطلاب واذا اتأخرت 10 دقايق ما يرضى توقع\n\nطريقة الشرح :\nيشرح من السلايدات في المحاضرات ويحل أسئلة في اللاب\nيوصلك المعلومة بكل الطرق ومبدع في الشرح\n\nالكويزات :\nسهلة غالبا وعليها 15% يعني ركز عليها ولا تخسرها\nكويز كل شابترين تقريباً\n\nالمياجر:\nالميجر الاول مو كومن وتكون أسئلته متوسطة\nالميجر الثاني والفاينل كومن بس حتعرف السؤال الي حطه من أسلوبه\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nيعطيك حقك وانا شخصيا كان وضعي حرج وكلمته وراعاني\n\nالصوت:\nصعب تنام لأن جيرانه كلهم يشتكوا منه 😛\n\nإضافات :\nكوميدي جداً (أستغرب ليه ما صار ممثل :p)\n\nإن شاء الله أفدتكم\nتحياتي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1053272-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/12", "user": "user3257", "ts": 1339281242000, "tid": 98439, "pn": 12}}]}', 1339281242000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-silvershine-acct110', 'stk-silvershine', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nراح نبدا فيها حبة حبة\n\nACCT110\n\nالشي الايجابي الوحيد ( ما يستاهل تتحمله عشانه )\n1- شرح كويس ويعطيك اوراق تفيدك ( الاوراق عبارة عن اجوبة لكم سؤال في الكتاب ) وتقدر تاخذها من اي طالب عنده (خذ رقم السؤال وتلاقي الجواب في السليوشن حق الكتاب ) وبالنسبة للشرح الكتاب ملللللللك ويغنيك عن كل دكتور = مو اجابية\n\nالسلبيات ( عد واغلط )\n1- دكتور قليل ادب بكل ما تعنيه الكلمة\nاخلاقه زي وجهو ويحب يرفع ضغط الطلاب ويسوي قلق في الكلاس ويقل ادبه\nمررة في طالب تاخر 5 دقايق سفل فيه وزعق عليه وقله انت غااااااااااااايب والطالب يجي برد يروح يرفع صوته\nصراحة استغربت من الطالب انه سكت لانه فعلا قل ادبه بشكل واضح\n2- الكلاس مدته 1:15 طبعا لو كان مروق يخليها 1:30 ولا العادة 1:50 مع التسفيل وقلة الادب\nيعني وقت كبير جدا من الكلاس يضيع في الهياط فاضي ودراسته مدري فين وتسفيل في الطلاب\nهذا غير انه مرة في تشابتر 3 دوبه بدا الشرح ماله نص دقيقة بعدين فجاة كذا جاته الحاله حقتو وقام ينافخ ويسأل الطلاب !!! شي طبيعي ما بيجابون لانهم ما فهمو شي من اللي قلته في نص دقيقة !!!\nوكمان تسفيل حق بزورة يعني يقولك انت ايش تخصصك واذا قلت اي تخصص غير الاكاونتنق حقرك حقارة ما بعدها\nهذا غير لو انك نزلت عنده والله اقولها وانا صادق ( بتقعد على اعصابك طول الترم )\nلانه حتى لو انت دافور ما حيسبك في حالك !!!\nتخيلو اعلى طالب في سكشنا ما شاء الله عليه جايب 87 في ميجر 2\nراح سفل فيه !!!!\nدور اي شي عشان يسفل لدرجة راح يطالع في كويزات الطالب وشاف عنده كويز 0 راح قاله ليه وليه وطوالة لسان !!\nهذا وهوا طالب A+ ما فيها كلام\nعاد ايش تتوقعو تعاملو مع طلاب الـC+ بيكون !!!\n\n3-انسان بثر وعليه ثقالة دم وكمان يقولك سماجة تسد النفس , ما انكر احيانا يقول حاجات تضحك الطلاب لكن الاغلب سماجة , واذا ضحك الطلاب بتكون تسفيل في طالب غالبا !!\n\n4- عشان لا تقولو انا مهمل ومدري ايش :\nهذي درجاتي / ميجر ون 35 من 50 , ميجر تو 81 من 100 , فاينل مدري ما نزلها\nقريدي النهائي / B+ ولله الحمد , لكن يشهد الله ما ركزت معاه الا يمكن تشابتر ون وتو والباقية صرت اكره كلاسه خلاص لدرجة اني سحبت من بعد ميجر تو لين نهاية الترم وخليت واحد يحضرني !!\nبشكل عام المادة سهلة ترى والكتاب مرة خطير , يعني نزل مع شهيد الاسلام ولا ميرغني كويزات سهلة ويريحك\nمو ذا اخلاق سيئة وكمان والله يحسسك ان المادة صعبة وهيا والله العظيم سهلة\n\n5- في ميجر تو افرج كلاسنا 66 والكلاس الثاني 68\n\nجس ينافخ يقول هذولي احسن منكم ومدري ايش !!\n\nعاد اترك لكم الحكم على حجم عقله من الموقف ذا\n\n6- انسى انك تسأله اي سؤال في الكلاس حتى لو ( متى الدرجات ) !!\n\n7- يسوي هيلب سيشن عبارة عن “هياط” سيشن يعني مسالتين مو معقولة يقعد عليها ساعتين !! وتراه ما يشرح بس يجاوب ويفترض انك جيت الهيلب سيشن وانت فاهم already\n\nيمكن بعضكم يقول هذا دكتور يشرح تمام وانت ظالمه وكذا بس بقولك تعال احضر عنده اي كلاس في نص الترم وشوف بنفسك\n\nالقريد النهائي للدكتور / شرح B+ اخلاق Dn يهتم براحة الطالب F\n\nوموفقين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1229000-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/17", "user": "SilverShine", "ts": 1369697229000, "tid": 98439, "pn": 17}}]}', 1369697229000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-blake-acct110', 'stk-blake', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Acct 110 - 2012\n\nالتحضير :\nيوميا - توقيع ع الورقة\n\nطريقة الشرح :\nسلايدات + سبورة + كتاب ، الدكتور شريييييح وفااااهم المادة تماما وخبرة له فترة طويلة يدرسها\nالافضل في acct 110 بلا منازع من ناحية الشرح\n\nالكويزات :\nسهلة جدا جدا جدا والغبي الي يضيع درجاتها لأنو مايحتاجلها مذاكرة\n\nالمياجر: كومن ( سكشنه دايما اعلى سكشن في الدرجات وأعلى افرج )\nالفاينلات : كومن\n\nالقريد النهائي:\n\n+A\n\nالصوت:\n\nواضح جدا وعآاالي + - يتكلم 65٪ عربي و 35٪ انجليزي\nوالانجليزي اكسنت مصري بحت ! لا تعتمد عليه في نطق الكلمات لانو عنده كم كلمه ينطقها غلط\n\nمميزات :\n\n1- يبغى مصلحتك بزيادة ويساعدك\n2- يوزع هاند اوت كل اسبوع فيها حل تمارين الكتاب ( 80٪ راح تجي منها في الميجر )\n3- يعمل هيلب سيشن اسبوعيا\n4- شرح بطل ويفهم بالأمثلة الواقعية\n5- كوميدي درجة اولى بامتياز - محشش يمشي على الارض\n\nسلبيات :\n\n1- رسميا المفترض الكلاس مدته ساعة وربع … لكن مع د.عمر الكلاس بالرااااااحة يكمل ساعة ونص إلى ساعتين !!!\n( ما اذكر اننا خرجنا ع الوقت إلا مرتين او ثلاثة في كل الترم ! )\n\n2- يطلع كثييير عن الشرح ( ممكن تفقد تركيزك او تتشتت )\n3- يسفل فيك اذا ماعرفت تجاوب او اذا اتأخرت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1254583-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/19", "user": "blake", "ts": 1377154419000, "tid": 98439, "pn": 19}}]}', 1377154419000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulla_yahia-acct110', 'stk-abdulla_yahia', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. عمرو عبدالحليم ]\n\nACCT 110 - Term 131\n- التحضير : يومياً - ورقة تمر على الطلاب ، ما يخصم على الغيابات لكن يعطي DN ,\n\n- طريقة الشرح : يشرح على سلايدات + سبورة - شرحه رهيب يعطيك أساس قوي في الأكاونتنق ، باين من شرحه أنه محضّر الدرس بامتياز ,\n\n- الكويزات : 6 كويزات سهلة - يأخذ أحسن 5 كويزات ,\n\n- المياجر : طويلة و تحتاج لمذاكرة - متوسطة الصعوبة ,\n\n- الفاينلات : نفس المياجر ,\n\n- القريد النهائي : +B\n\n- الصوت : واضح و جهور قد يصل لحد الإزعاج ,\n\n- إضافات : الدكتور عملي درجة أولى + يشرح بقلبه و بإخلاص + يهتم بمصلحة الطالب ، لكن تعيبه طباعه الحادة و عدم ترحيبه بالأسئلة وقت الكلاس ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1323181-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/25", "user": "Abdulla_Yahia", "ts": 1390840268000, "tid": 98439, "pn": 25}}]}', 1390840268000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mhm14-acct110', 'stk-mhm14', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Acct 110 - term 132\n\nالتحضير: يوميا، ورقة تمشي بين الطلاب، و لازم تحضر بسكشنك، ما يسمح تحضر سكشن ثاني\n\nطريقة الشرح: ممتازة بشكل ما تتصوره، يوصل لك المعلومة بشكل ممتاز و مبسط و يخليك تستمتع بالمادة و يحببها لك\n\nالكويزات: 6 كويزات يشيل أسوأ واحد و السؤال سهل نفس فكرة الهانداوت اللي يعطيك اياه\n\nالمياجر: تتكون من 10 أسئلة اختيار متعدد و كم من سؤال كتابة جمل و باقي الإختبار حل مسائل، تكون المسائل من نفس الأفكار الموجودة بالهاندأوت و الهوموركات\n\nالفاينلات: تماما مثل المياجر و كان 4 تشباتر فقط\n\nالقريد النهائي: A+\n\nالصوت: عالي جدا، الكلاسات المجاورة تفهم الدرس بعد 🙂\n\nإضافات: شرحه رائع و ممتاز … أنصح الطلاب بالذات طلاب المحاسبة إنهم ياخذوا الكورس معاه لأن الكورس يبني أساس الطالب بالمحاسبة و إذا كان أساسك ضعيف بتتعب بعدين\nبس صراحة أخلاقه بالفصل ما عجبتني، دائما يعلق و إذا طلعك تحل سؤال على السبورة و ما حليت بيمسكها عليك شهر لو أكثر، لكن للأمانة أخلاقة خارج الفصل ممتازة تحسه إنسان آخر 🙂\n\nالله يوفقه وين ما راح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1370408-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/27", "user": "MHM14", "ts": 1400931282000, "tid": 98439, "pn": 27}}]}', 1400931282000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10207-acct110', 'stk-user10207', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 110 – Term 141\nالتحضير: ورقة تمر أول الكلاس. ما ينفع تتأخر لأنه بيسجلك غياب.\nطريقة الشرح ممتازة. يشرح على السلايدات ويقرأ من الكتاب. يشرح كل معلومة بالكتاب بالتفصيل مع الأمثلة والتوضيحات على السلايدات والسبورة.\nبعد ما يخلص الشبتر. يحل مع الطلاب مسائل من الكتاب ويوزع حلول هذه المسألة على الطلاب.\nبعض الأحيان يتكلم عربي ويعلق على المصطلحات المحاسبية الي ما يعرفها الطلاب.\nالكويزات سهلة جداً. نفس فكرة الأوراق الي يوزعها. والي موجودة بأسئلة الكتاب.\nيعطيك في السمستر 6 كويزات ويحذف أسوء كويز. الكويزات عليها 5% من المجموع.\nالمياجر والفاينلات كومن بكل السكاشن. المياجر نفس فكرة أسئلة الكتاب والهومورك والأراق.\nميجر 1 عليه 20%. ميجر 2 عليه 30% والفاينل عليه 30%.\nالدكتور محترم جداً. عكس كلام طلاب كثير هنا بموضوع التقييم.\nيرحب بالطلاب في الأوفيس أور.\nبعض الأحيان يعطي كلاس يوم الأربعاء تحل معه تمارين من الأوراق والكتاب.\nقبل الميجر يعطي كلاس مراجعة أو إذا أحد عنده سؤال. (يوم الأربعاء).\nقبل الفاينل يعمل مراجعة تفصيلية على الماتيريال.\nقبل الفاينل يمدد وقت الأوفيس أور للطلاب.\nفي الكلاس، يطلع الطلاب على الوقت وأحياناً يأخذ “بالكثير” 5 دقائق زيادة.\nدمه خفيف جداً ويحب يضحك الطلاب.\nيضغط الطلاب كثير. بعد ما يخلص الشبتر يحط أسئلة الهومورك بالموقع. وفي خلال أسبوع تحلها مهما كنت مضغوط من كورسات ثانية.\nيعطي DN للي ما يحضروا الكلاس. لكن ما يخصم على الغيابات.\nالصوت واضح جداً. لكن لغته الإنجليزية سيئة ويتكلم إنجليزي بلهجة مصرية. 🤪\nيحضر الكلاس على الوقت وما يتأخر.\nممنوع عنده تحضر بالسكشن الثاني.\nيشرح طول الكلاس بدون توقف. فعشان كذا أحياناً ما يتقبل أحد يقاطعه أو يسأله سؤال. لكن بعض المرات يتجاوب.\nلكن ورغم السلبيات، يبقى الدكتور جداُ ممتاز (أفضل مدرس رأيته في الجامعة لحد الآن).\nملتزم جداً بالكتاب. يعتمد عليه كثير وهذا شيء كويس.\nأفضل دكتور رأيته مخلص في عمله ومهتم لمستوى الطلاب.\nيحب الطلاب المتميزين والي يشاركوا بالكلاس.\nأنصح الطلاب به سواء كانوا محاسبة أو غير ذلك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420975-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/29", "user": "user10207", "ts": 1421788808000, "tid": 98439, "pn": 29}}]}', 1421788808000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_taki-acct110', 'stk-abu_taki', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Acct110-Term 151\n\nالتحضير : يحضر بورقة تمر على الطلاب بداية كل محاضرة … بداية السمستر ممكن يعديها اذا تأخرت 10-15 دقيقة ويخليك تحضر\nبس بعدين رح يشدد على التأخير وغالبا مارح يسمح لك تحضر اذا تأخرت اكثر من 10 دقايق خاصة اذا تكرر التأخير من الطلاب\nطبعا ما يسمح بالميك أب ابدا\nطريقة الشرح : ممتازة … مارح تلقى أفضل منه في الشرح … يشرح بضمير وإخلاص … يستخدم الباوربوينت والسبورة والكتاب وكل شيء للشرح … ولا تستغرب اذا شفته يكتب على جدار الكلاس عشان تثبت المعلومة في مخك !\nالكويزات : 6 كويزات عبارة عن مسائل بسيطة … ويحذف درجة اسوأ كويز\nالمياجر: معظم الميجر حل مسائل حسابية … وشوية فقرات اختيارية و اسئلة مقالية … مستوى الاسئلة من متوسط الى صعب نوعا ما لكنه مقدور عليه للي مركز في الكلاس ويذاكر الهاند أوت + الاونلاين هوموورك\nالفاينلات : نفس المياجر\nالقريد النهائي: A\nالصوت: عالي جدا\nإضافات : الدكتور عمر من الدكاترة اللي لهم مكانة خاصة في قلبي … يقدّس الاكاونتنق وتقريبا في كل كلاس يذكرنا بأهمية الاكاونتنق ويحفز طلاب التخصصات الاخرى على التحويل للاكاونتنق … ممكن تفكره عصبي في بداية الترم بس هو طيب وشخصيته كوميدية ومحبوبة من الطلاب …\nعنده هاند اونت مفيد جدا والاسئلة اللي في المياجر والفاينلات نفس الافكار بس مستواها أعلى … انصحك تنزل معه وبالذات اذا كان تخصصك اكاونتنق … من ناحية الدرجات فالدكتور مارح يعطيك الا حقك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437601-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/30", "user": "Abu_Taki", "ts": 1451601380000, "tid": 98439, "pn": 30}}]}', 1451601380000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-llabdulmalikll-acct110', 'stk-llabdulmalikll', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 110 - 151\n\n- التحضير : في ورقة يوزِّعها ببداية كل محاضرة تمر على الطلاب و يوقعون عليها , ما يسمح بالـMake Up و ما يقبل التأخير , لو تأخَّر الطالب بحدود 10 دقايق يُعتبر غايب و لو حضر باقي المحاضرة .\n\n- طريقة الشرح : تقليديَّة قديمة مملة جداً , يتكلم و يتكلم و يتكلم و ما تدري إلَّا و هو مخلِّص الـChapter , المحاضرة عبارة عن ساعة و ربع كلَّها على رتم واحد من الكلام فوقه كلام فوقه كلام , يرفض إنِّك توقِّف شرحه عشان تسأل , كل اسألتك لازم تجمِّعها و تسأله بعد نهاية المحاضرة .\n\n- الـQuizzes : عطانا 7 على ما أذكر و حذف واحد منها .\n\n- الصوت : عالي و مزعج جداً , من الصعب إنِّك تنوم عنده من صوته , عادي جداً تكون برَّا الـClass و تسمع و تفهم كلامه كأنِّك داخل الـClass .\n\n- الـGrade : أخذت C .\n\n- إضافات : ما يخصم على الغياب حتى لو كان باقي للطالب على الـDN غياب واحد , ما يلتزم أبداً بمدة المحاضرة , يزيد عليها 10 أو 15 دقيقة و من كثر ما يسويها اعتادوا عليه الطلاب بالرغم من إنَّه يبدأ مع أول ثانية من المحاضرة , يلزم الطلاب بالحضور عشان يعرفون مواعيد الـQuizzes و درجاته و درجات الـMajors بعد , لا تستغرب أبداً لو كتب عالجدار أو وقَّف فوق الطاولة عشان يشرح .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438198-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/31", "user": "llABDULMALIKll", "ts": 1452119485000, "tid": 98439, "pn": 31}}]}', 1452119485000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-acct110', 'stk-guest', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 110 - 151\n\n- التحضير : التحضير ورقة تدور على الطلاب ، مافيه خصم على الغياب لكن 9 غيابات DN ،يهزئ المتأخرين وماعنده مشكلة يضيع 10 دقايق تهزيء في شخص متأخر\n\n- طريقة الشرح : سلايدات يعرض فيها النقاط ويشرحها ، مشكلته إنه طول الكلاس الساعة وربع يتكلم ويتكلم ويتكلم ، فيوصل مرحلة إنك خلاص تقفل مخك ماتقدر تستوعب (يعني مايهتم أنت فهمت ولامافهمت أهم شيء يشرح النقطة ويمشي قبل السيلابس)\n\n- الـQuizzes : عطانا 7 على ما أذكر و حذف واحد منها . المجموع 5%\n\n- الصوت : عالي و مزعج جداً , من الصعب إنِّك تنوم عنده من صوته , عادي جداً تكون برَّا الـClass و تسمع و تفهم كلامه كأنِّك داخل الـClass .\n\n- إضافات : دقيق بالتصحيح ولا يمكن يدفك ولا بربع درجة على قولتهم ، الرجال راعي تجديع كلام وتجريح أحيانا ،،، +انتبه تزل وتقول معلومة يعنني فاهم وتطلع غلط …\nسويتها مرة عطاني نظرة تمنيت أن تنشق الأرض وتبلعني", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1444940-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/32", "user": "Guest", "ts": 1458949352000, "tid": 98439, "pn": 32}}]}', 1458949352000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-waleedx11-acct110', 'stk-waleedx11', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "161 ACCT110 TERM\n\nالتحضير : ورقة تمر على الطلاب بداية الكلاس وكل طالب يوقع عند اسمه . الغياب التاسع ب DN و ما يعطي بونص عالحضور. باختصار : اللي ماغاب ولا مرة واللي غاب ٨ مرات كلهم سواسية عنده .\n\nطريقة الشرح : والله ثم والله ويشهد علي ربي إنه أفضل دكتور يشرح مر علي في حياتي الأكاديمية (نقطة) !\n\nالكويزات : 6 كويزات طوال الترم عليها 5% سهلة جدًا للي مذاكر وفاهم ويحذف أسوأ كويز وما يحذف الفواصل أبدًا ولا يقرب الدرجة . يعني مثلا لو ماخذ 4.889 من 5 ما تتقرب وتنزل لك زي ماهي . نفس الكلام واجبات الأونلاين عليها 15% وبرضو ما تتقرب وتاخذها زي ماهي.\n\nالمياجر: طويلة جدًا وتحتاج تركيز وقد ما تذاكر تحصل ، دكتور عمر يوزع هانداوت في كل تشابتر جديد مفيدة في المذاكر يعني لو ذاكرتها (بفهم كامل وليس بحفظ) أضمن لك ٧٥٪ من الاختبار في الجزء العملي ولكن هي مش كل شيء لانو ضروري مذاكرة الكتاب برضو لأن في مسائل مقالية في المياجر واختيار من متعدد برضو.\n\nالفاينلات : نفس سستم المياجر.\n\nالقريد النهائي: والله لو في فوق ال A+ كان عطيته.\n\nالصوت: يتكلم باللكنة المصرية الانجليزية . أول كلاس بتضحك بس بعدين راح تتعود عليها هههههههههههههههه . وماشاء الله صوته جدًا عالي لدرجة الكلاس الثاني يسمعونه.\n\nإضافات :\n\n١- الدكتور الله يسعده يبذل قصارى جهده علشان تطلع بفهم وقريد ممتاز من المادة.\n\n٢- يسوي هيلب سيشن كل أربعاء في بريك الغداء جدا مفيدة يحل فيها الهانداوت ويتقبل الأسئلة فيها.\n\n٣- الدكتور فكاهي ومضحك إلى أبعد الحدود لدرجة والله كنا ندمع من الضحك في كلاسه.\n\n٤- لا تحاول تقاطعه أو تسأله عن شيء وهو يشرح لأن بتروح عليك غلطة و راح يهزأ فيك 😆 😆 . هو بيخصص وقت للأسئلة في الكلاس ساعتها أسأله اللي تبي.\n\n٥- يتقبل الأسئلة بصدر رحب في الأوفيس آور و متواجد لخدمة الطلاب.\n\n٦- الدكتور عيبه أنه يستنقص الطلاب حقين التخصصات الادارية الاخرى ومتعصببببب لأبعد الحدود للمحاسبة ، كل الطلاب اللي بدعوا في المياجر في كلاسنا يقولهم هذاكم جبتوا درجات عالية فأختاروا تخصصكم المناسب بذكاء ( يعني بالعربي حولوا محاسبة 🤣)\n\nكلمة أخيرة : خليه خيارك الأول لأن والله راح يأسسك صح في علم المحاسبة وراح تستفيد منه بشكل جدا كبير وراح تدعيلي .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466880-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/33", "user": "waleedx11", "ts": 1485216774000, "tid": 98439, "pn": 33}}]}', 1485216774000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jafar_15-acct110', 'stk-jafar_15', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Acct110-162\n\nالتحضير : يومي عن طريق ورقة يمررها ، ومايقبل بالميكب ابدا ، طبعا التحضير ماعليه اي درجة ولا ياثر في درجتك. يعني لو تحضر سكشن ثاني بيحسبك غياب لكن مايخصم عليك درجة، ولكن ياثر في DN اذا جبت ٩ غيابات\n\nطريقة الشرح : ممتازة جدا ، يشغل سلايدات تابعة للكتاب ويشرح عليها ، وبعد نهاية كل شابتر في هانداوت مفيدة للواجب والكويزات\n\nالكويزات : سهلة جدا لو تذاكر الهانداوت لحاله ، مايجيب الا مسائل فقط\n\nالمياجر: متوسطة الى صعبة وهي كومن ، واذا كان ميرغني يدرس في نفس الترم خذ التحديد من طلابه تجي نفس المسائل بتغيير الارقام+ نفس الاسئلة المقالية غالبا\n\nالفاينلات : كومن ، ونفس نظام المياجر\n\nالصوت: يوصل الى السكن من قوته ماشاء الله\n\nإضافات : الدكتور شريييييح ، لكن كتصحيح شدييييد جدا ، يعني تغلط في نص فقرة والنص الثاني صح يحسب لك كلها غلط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474058-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/34", "user": "Jafar_15", "ts": 1496065824000, "tid": 98439, "pn": 34}}]}', 1496065824000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aziiz99-acct110', 'stk-aziiz99', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "acct110-162\n\nالدكتور عمرو افضل دكتور درسني بهالجامعه\nشرحه خرافي و كلاسه يمر بسرعه مع انه كان كثير يأخذوقت زياده عالكلاس\nبكل اختصار تبي تفهم الماده صح نزل معه و ركز في الشرح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1502347-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/35", "user": "aziiz99", "ts": 1542143732000, "tid": 98439, "pn": 35}}]}', 1542143732000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faris_alali-acct110', 'stk-faris_alali', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 110 - 181\n\nالتحضير : كل كلاس يجيب ورقة و يمررها بين الطلاب\n\nالشرح : حماااااااسي ويبي الكل يفهم و يضرب امثلة حياتية ترسخ الفكرة في راسك و حضورك فالكلاس راح يفرق في حل الكويزات و الاسايمنت و المياجر و الفاينل لأن كل نقطة يقولها مهمة و اذا تخصصك محاسبة لازم تنزل عنده لأنك اذا تأسست صح عنده بترتاح\n\nالكويزات : عطانا 6 كويزات اخذ افضل 5 منهم و بشكل عام بسيطين\n\nالمياجر و الفاينل : صحيح إنها كومن لكن الهاند اوت الي بيعطيك وياها اذا فهمتها فجزء الرتن بتحله سهالات لكن الخيارات لازم تقرأ الكتاب\n\nالصوت : لهجة مصرية تحفة احتمال تضحك كل كلاس يا على لهجته ولا على شطحاته\n\nالثريد النهائي : A++++\n\nاضافات : لازم تتحمل التهزيئ اذا تأخرت أو اذا سأل سؤال و جاوبته غلط لأنه يحب يدور الغلط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503869-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/36", "user": "Faris_Alali", "ts": 1545347021000, "tid": 98439, "pn": 36}}]}', 1545347021000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kbsc-acct110', 'stk-kbsc', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور :*\n\nعمر عبدالحليم\nالمادة: *\n\nAcct110\nطريقة الشرح : *\n\nممتازه عن طريق السلايدات يستخدم السبوره لشرح النقاط المهمه\nالكويزات :\n\nمتوسطه تميل للسهوله\nالمياجر/ميد:\n\nكومن\nالفاينل :\n\nكومن\nطريقة التحضير :\n\nورقة تمر وتوقع عليها\nالقريد النهائي الخاص بك :\n\nA\nاضافات:\n\nصوته مزعج احيانا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507355-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/37", "user": "KBSC", "ts": 1552816401000, "tid": 98439, "pn": 37}}]}', 1552816401000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_battah-acct110', 'stk-mohammed_battah', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT-110-191\nالتحضير : ورقة تمر على الطلاب وتوقع فيها\nطريقة الشرح : يبدا يستعرض ابرز النقاط اللي اخذناها اول ثم يبدا يشرح المومضع بشكل اسطوري شرحه يخليك تفهم غصب حتى لو انت نايم + الدكتور عليه فصلات مضحكة تستمع بالكلاس معاه\nالكويزات : ٤ كويزات كانت نفس الهاند اوت وكانت متوسطه الى سهله\nالمياجر: ميجرين واحد ٢٥ والثاني ٣٠ كانت متوسطه فيها مسائل عمليه نفس الهاند اوت وفيها اختيارات من الكتاب نفسه ( لازم تقرا الكتاب وتفهمه عشان تجيب فيهم درجة كويسة)\nالفاينلات : فاينال عليه ٣٠ كان نفس الميجر الثاني لكن كثر المسائل\nالقريد النهائي:A+\nالصوت: واضح بزيادة احيانا يطلع برا الكلاس وتسمعه\nإضافات : نصيحة اذا حصل لك لاتنزل مع غيره ماراح تندم ابدا وماراح تعرف قيمته الا اذا جربت غيره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518256-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/38", "user": "Mohammed_Battah", "ts": 1577129128000, "tid": 98439, "pn": 38}}]}', 1577129128000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nawafmkz-acct110', 'stk-nawafmkz', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Acct110-191\nالتحضير : ورقة تمر على الطلاب، اللي يتأخر مرة يقول له لا توقع.\nطريقة الشرح : من سلايدات الكتاب ويستخدم السبورة، الشرح غالبا واضح مع أمثلة كثير ومشكل بين العربي والانقليزي،\nالكويزات : 3 كويزات فقط قريبة من الهاند اوت\nالمياجر: ميجرين كومن\nالفاينلات : نفس المياجر\nالقريد النهائي: B\nالصوت: واضح جدا وأحيانا مزعج\nإضافات :\nالدكتور يمشي على السيلبس بالضبط يعني في أول الأسابيع بيكون داعس شوي عشان يتقدم مع أن الطلاب جديدين على مادة المحاسبة.\nأسلوب الدكتورأشوفه مستفز، ممكن مرة تسأل سؤال غبي ويصير يضرب فيك المثل بكل كلاس أو عشان أي شي ثاني\nالتصحيح: يعطيك حقك بالضبط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518439-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/39", "user": "NawafMKZ", "ts": 1577655355000, "tid": 98439, "pn": 39}}]}', 1577655355000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-paco-acct110', 'stk-paco', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(Acct110 - 201 (Online\n\nالتحضير : بداية المحاضرة بالاسماء وينادي على اسماء الغايبين بالنهاية عشان لو جاو متأخر\n\nطريقة الشرح : من السلايدات ويكتب عليها والخط ممكن يكون مو واضح بس بتتعود عليه\n\nالكويزات : حل الاسايمنت + الهاند اوت وبتشوفه سهل\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A+\n\nالصوت: واضح وعالي مع لهجة مصرية 😆\n\nإضافات : الدكتور ما يقصر يرسل ملف اول بأول فيه الغيابات وواحد ثاني فيه درجات الاختبارات\n+ وقت الاختبارات يكون موجود على ايميله لو صارت لك مشكلة تقنية او شي تقدر تكلمه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527763-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/42", "user": "Paco", "ts": 1610290331000, "tid": 98439, "pn": 42}}]}', 1610290331000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bu-omran-acct110', 'stk-bu-omran', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(Acct 110-201 (ONLINE\n\nالتحضير : في البلاكبورد يحضر بداية الكلاس واذا تاخرت يحضرك في النهاية وما يعطي ليت (يعني عادي تدخل اخر الكلاس وتقوله يحضرك مب مشكلة) احيانا يسأل اثناء الكلاس والي ما يرد يحطه غياب (في الغالب يسأل اول اسم في الكشف)\nطريقة الشرح : سلايدات, شرحة ممتاز لكن مشكلته ما يسجل المحاضرة وهذه اكبر مشكلة فيه خصوصا ان ذي المادة موضوعاتها متسلسلة, اذا ما فهمت الوحدة الاولى مب تفهم الثانية وكذا, وهذه المشكلة واجهتي وصرت ادخل المحاضرة واسحب عليه, واخذت المادة self study, وللاسف قلنا له يسجل المحاضرات بس مارضى\nالكويزات :عطانا 3 كويزات, كلهم في موقع وايلي بلس (الدكتور يحط الرابط في البلاكبورد) الاول سهل جداا, والثاني سهل, الثالث يميل للصعوبة, اغلب الاسئلة اختر ويعطينا سؤال او سؤالين حل مسائل -كل الاختبارات اختبرناهم بدون كاميرا, حتى الفاينل!-\nالمياجر:مافي مياجر, لكن فيه اختبارات كثييرة, في اختبار كله نظري (اختيارات) وكان من سهل الى متوسط, في اختبار كله معادلات وكان نفس فكرة الهوموورك بالضبط بس غير الارقام\nالفاينلات :كومن\nالقريد النهائي:B\nالصوت:عاالي جددداا لدرجة انه يجيب الصداع (ما انصحك تدرس بعد كلاسه يعني خل كلاسه نهاية الدوام), بتتعود عليه بعدين\nإضافات :الدكتور لو كان يسجل المحاضرة كان عطيته A لان ذا الشيء مهم جددا, ما يعطي بونص, ما يعطيك فرصة عشان تسأله اثناء الكلاس, احيانا يضحك اذا فصل او تنرفز, يرد ع الايميل بسرعة يعني اذا انقطع عليك النت كلمه ويعيده لك, في طالب صار عنده مشوار وقت الاختبار وعاده له, اذا كنت بتذاكر اول بأول انصححححك بقوة تسجل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527779-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/43", "user": "Bu-Omran", "ts": 1610296779000, "tid": 98439, "pn": 43}}]}', 1610296779000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-idk-acct110', 'stk-idk', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT110 - T241\n\nالتحضير :\nيوزع ورقة على الكل وكل واحد يحضر عمره\n\nطريقة الشرح :\nيشرح من السلايدات شرحه كويس اذا انتبهت معه بس يقروش الواحد لازم تكون مركز معه 24 ساعة ولا بياكلك بس يعني شرحه زين والحلو ان بعد كل تشابتر يحل هانداوت\n\nالكويزات :\nمتوسطة وتميل الى السهولة يعني ماهي زي صعوبة الميجر, ذاكر من السلايدات وامورك طيبة وحل الهاندوات\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nB+\n\nالصوت:\nصوته عالي مرا\n\nإضافات :\nصراحة الدكتور هو الي ماسك هذي المادة ومالك الا تنزل عنده الدكتور كويس يعني بس ماهو الافضل مشكلته انه غير متعاون مع الطالب مرا يعني ما يأجل كويزات ولا شيء واسلوبه مو الافضل بس بتتعودعليه, هو كذا طبعه فما يمديك تغيره, بس يعني زي ما قلت الدكتور كويس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537879-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/44", "user": "idk", "ts": 1730825113823, "tid": 98439, "pn": 44}}]}', 1730825113823, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-stallion-acct110', 'stk-stallion', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f98439", "n": "Dr. M Amr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT 110 - T241\nالتحضير : كل كلاس ورقي\nطريقة الشرح : يفتح السلايدات بس يشرح بطريقته وامثلته الخاصة وشرحه ممتاز صراحة بس يحتاج تركيز\nالكويزات : سهلة\nالمياجر: كومون\nالفاينلات :كومون\nالقريد النهائي: A\nالصوت: واضح لكن عالي جدا ومزعج\nإضافات : الدكتور يكره الاسئلة الغبية لو تسأله بياكلك بقشورك من اول الترم لنهايته لكن خلك ساكت ومنتبه في الشرح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1538706-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-amr/98439/45", "user": "Stallion", "ts": 1735914792164, "tid": 98439, "pn": 45}}]}', 1735914792164, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-brilliant_accountant-acct110', 'stk-brilliant_accountant', 'ACCT 110', 'doc', '{"docs": [{"id": "stk-dr-f99892", "n": "Dr. Ammr Kurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Acct 201 ترم 112\nAcct 302 ترم 122\n\nالتحضير : ينادي في بداية الكلاس وما ينسى التحضير\nطريقة الشرح : من السلايدات ويحل امثله\nالميدتيرم و الفاينل : تتكون من اختيارات واسئلة مقالية ومسائل\nالصوت: واضح واكسنت ممتاز\nإضافات :\n\nدكتور فاهم و متمكن من المادة لكن شغله كثير ( 3 كيس ستدي ، واجبات اونلاين ، بروجكت) ويبغى لك تتعب معاه عشان تطلع بقريد ، الحمدلله كل الكورسين اخذت A+ بدون دف وطريقتي في المذاكرة بعد فضل الله لها دور كبير ، اولا تقرأ الكتاب و تفهم الكونسبت وبعدها تبدأ تحل كل اسئلة الكتاب وحاول تحلها مرة ومرتين وثلاث ومع مرور الوقت تصير متمكن من حل كل انواع المسائل وفي اقصر وقت ممكن وهذا اللي كان ناقص اغلب الطلاب ، دائما يقولون الوقت غير كافي وذلك بسبب قلة الممارسة\n\nبالنسبة للغياب فهو لا يخصم درجات على الغياب فقط انتبه من الـDN", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1333969-acct110", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ammr-kurdi/99892/11", "user": "Brilliant_Accountant", "ts": 1393308110000, "tid": 99892, "pn": 11}}]}', 1393308110000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
